defmodule Platform.Web.Endpoint do
  use Phoenix.Endpoint, otp_app: :acme

  socket "/socket", Platform.Web.UserSocket,
    websocket: true,
    longpoll: false

  # Serve at "/" the static files from "priv/static" directory.
  #
  # When code reloading is disabled (e.g., in production),
  # the `gzip` option is enabled to serve compressed
  # static files generated by running `phx.digest`.
  plug Plug.Static,
    at: "/",
    from: :acme,
    gzip: not code_reloading?,
    only: Platform.Web.static_paths(),
    raise_on_missing_only: code_reloading?

  # Code reloading can be explicitly enabled under the
  # :code_reloader configuration of your endpoint.
  if code_reloading? do
    plug Phoenix.CodeReloader
    plug Phoenix.Ecto.CheckRepoStatus, otp_app: :acme
  end

  plug Plug.RequestId
  plug Plug.Telemetry, event_prefix: [:phoenix, :endpoint]

  # before the body is read: a client over its limit costs almost nothing
  plug Platform.Web.RateLimit

  plug Plug.Parsers,
    # a multipart body (an upload) may be larger than the JSON and form ones
    parsers: [:urlencoded, {:multipart, length: 6_000_000}, :json],
    pass: ["*/*"],
    # a client that stops sending its body is cut off, not waited for
    length: 1_000_000,
    read_timeout: 10_000,
    json_decoder: Phoenix.json_library()

  plug Plug.Head
  plug App.Router
end
